// Formulario de ajuste manual de stock que comparten Inventario y el Editor de producto.
// Abre el formulario para una variante, valida con validarAjusteStock, envía el ajuste y
// deja los errores por campo; cada vista decide qué aviso mostrar y cómo recargar.
import { reactive, ref } from 'vue'
import productoService from '@/services/productoService'
import { validarAjusteStock } from '@/utils/inventario'

/**
 * @param {{ alGuardar: (respuesta: object) => (void|Promise<void>), alFallar: (mensaje: string) => void }} acciones
 */
export function useAjusteStock({ alGuardar, alFallar }) {
  const ajuste = reactive({ varianteId: null, tipo: 'entrada', cantidad: 1, motivo: '' })
  const erroresAjuste = ref({})

  function abrirAjuste(variante) {
    Object.assign(ajuste, { varianteId: variante.id, tipo: 'entrada', cantidad: 1, motivo: '' })
    erroresAjuste.value = {}
  }

  async function guardarAjuste() {
    const { errores, datos } = validarAjusteStock(ajuste)
    erroresAjuste.value = errores
    if (Object.keys(errores).length) return

    try {
      const respuesta = await productoService.ajustarStock(ajuste.varianteId, datos)
      ajuste.varianteId = null
      await alGuardar(respuesta)
    } catch (e) {
      // Errores por campo junto al formulario; los demás, como aviso de la vista.
      erroresAjuste.value = e.errores ?? {}
      if (!Object.keys(erroresAjuste.value).length) alFallar(e.message)
    }
  }

  return { ajuste, erroresAjuste, abrirAjuste, guardarAjuste }
}

// Listado paginado del panel con filtros (pedidos, productos, inventario, usuarios, devoluciones).
//
// Reúne lo que antes repetía cada vista: el estado de carga y error, volver a la página 1
// cuando cambia un filtro, esperar a que se deje de escribir en la búsqueda y cambiar de página.
//
// Uso:
//   const { filtros, resultado, cargando, error, cargar, irAPagina } =
//     useListadoPanel((f) => pedidoService.listar(f), { estado: '', desde: '', hasta: '' })
import { onBeforeUnmount, reactive, ref, watch } from 'vue'

/** Milisegundos sin escribir antes de buscar (evita una consulta por cada tecla). */
export const ESPERA_BUSQUEDA_MS = 350

/**
 * @param {(filtros: object) => Promise<object>} consultar Pide una página a la API con los filtros
 * @param {object} filtrosIniciales Filtros propios de la vista (además de q y pagina)
 * @param {object} resultadoInicial Campos extra del resultado vacío (por ejemplo el umbral de stock)
 */
export function useListadoPanel(consultar, filtrosIniciales = {}, resultadoInicial = {}) {
  const filtros = reactive({ q: '', ...filtrosIniciales, pagina: 1 })
  const resultado = ref({ items: [], total: 0, paginas: 0, ...resultadoInicial })
  const cargando = ref(true)
  const error = ref('')
  let temporizador = null

  async function cargar() {
    cargando.value = true
    error.value = ''
    try {
      resultado.value = await consultar(filtros)
    } catch (e) {
      error.value = e.message
    } finally {
      cargando.value = false
    }
  }

  function reiniciarYCargar() {
    filtros.pagina = 1
    cargar()
  }

  function irAPagina(pagina) {
    filtros.pagina = pagina
    cargar()
  }

  // Los filtros de selección (semáforo, listas, fechas) consultan de inmediato...
  const inmediatos = Object.keys(filtros).filter((clave) => !['q', 'pagina'].includes(clave))
  watch(() => inmediatos.map((clave) => filtros[clave]), reiniciarYCargar)

  // ...y la búsqueda espera a que se deje de escribir.
  watch(() => filtros.q, () => {
    clearTimeout(temporizador)
    temporizador = setTimeout(reiniciarYCargar, ESPERA_BUSQUEDA_MS)
  })
  onBeforeUnmount(() => clearTimeout(temporizador))

  return { filtros, resultado, cargando, error, cargar, irAPagina }
}

import { createApp } from 'vue'
import { createPinia } from 'pinia'
import App from './App.vue'
import router from './router'
import { alExpirar } from './services/api'
import { useAuthStore } from './stores/auth'
import './assets/css/base.css'

const app = createApp(App)
app.use(createPinia())
app.use(router)

// Si la API rechaza el token (vencido o cuenta desactivada), se cierra la sesión.
// Solo se envía al login si la página actual exige sesión; en la tienda se sigue navegando.
alExpirar(() => {
  useAuthStore().cerrarSesion()
  const actual = router.currentRoute.value
  if (actual.matched.some((ruta) => ruta.meta.requiereSesion)) {
    const destino = actual.path.startsWith('/panel') ? 'acceso-personal' : 'login'
    router.push({ name: destino, query: { redirect: actual.fullPath, expirada: '1' } })
  }
})

app.mount('#app')

// Rutas de la aplicación (Vue Router) y protección por rol.
import { createRouter, createWebHistory } from 'vue-router'
import { useAuthStore } from '@/stores/auth'
import HomeView from '@/views/HomeView.vue'
import CatalogoView from '@/views/CatalogoView.vue'

const routes = [
  { path: '/', name: 'inicio', component: HomeView },
  { path: '/catalogo/:marca', name: 'catalogo', component: CatalogoView, props: true },
  { path: '/producto/:slug', name: 'producto', component: () => import('@/views/ProductoView.vue'), props: true },
  { path: '/contacto', name: 'contacto', component: () => import('@/views/ContactoView.vue') },
  { path: '/login', name: 'login', component: () => import('@/views/LoginView.vue'), meta: { soloInvitados: true } },
  // Ingreso del vendedor y del administrador (enlace del candado en el pie de página).
  { path: '/acceso-personal', name: 'acceso-personal', component: () => import('@/views/LoginView.vue'), meta: { soloInvitados: true, personal: true } },
  { path: '/recuperar', name: 'recuperar', component: () => import('@/views/RecuperarView.vue'), meta: { soloInvitados: true } },
  { path: '/restablecer', name: 'restablecer', component: () => import('@/views/RestablecerView.vue') },
  { path: '/mi-cuenta', name: 'mi-cuenta', component: () => import('@/views/MiCuentaView.vue'), meta: { requiereSesion: true } },

  // Cliente: compra y pedidos
  {
    path: '/checkout',
    name: 'checkout',
    component: () => import('@/views/CheckoutView.vue'),
    meta: { requiereSesion: true, roles: ['cliente'] },
  },
  {
    path: '/mis-pedidos',
    name: 'mis-pedidos',
    component: () => import('@/views/MisPedidosView.vue'),
    meta: { requiereSesion: true, roles: ['cliente'] },
  },
  {
    path: '/mis-pedidos/:id(\\d+)',
    name: 'mi-pedido',
    component: () => import('@/views/MiPedidoView.vue'),
    props: true,
    meta: { requiereSesion: true, roles: ['cliente'] },
  },
  {
    // Vuelta del widget de Wompi: verifica la transacción ?id=...
    path: '/pago/resultado',
    name: 'pago-resultado',
    component: () => import('@/views/PagoResultadoView.vue'),
    meta: { requiereSesion: true, roles: ['cliente'] },
  },

  {
    path: '/panel',
    component: () => import('@/views/panel/PanelLayout.vue'),
    meta: { requiereSesion: true, roles: ['admin', 'vendedor'] },
    children: [
      { path: '', name: 'panel', component: () => import('@/views/panel/PanelInicio.vue') },
      { path: 'productos', name: 'panel-productos', component: () => import('@/views/panel/ProductosAdmin.vue') },
      {
        path: 'productos/nuevo',
        name: 'panel-producto-nuevo',
        component: () => import('@/views/panel/ProductoEditor.vue'),
        meta: { roles: ['admin'] },
      },
      {
        path: 'productos/:id(\\d+)',
        name: 'panel-producto',
        component: () => import('@/views/panel/ProductoEditor.vue'),
        props: true,
      },
      { path: 'pedidos', name: 'panel-pedidos', component: () => import('@/views/panel/PedidosAdmin.vue') },
      {
        path: 'pedidos/:id(\\d+)',
        name: 'panel-pedido',
        component: () => import('@/views/panel/PedidoAdmin.vue'),
        props: true,
      },
      { path: 'inventario', name: 'panel-inventario', component: () => import('@/views/panel/InventarioAdmin.vue') },
      { path: 'devoluciones', name: 'panel-devoluciones', component: () => import('@/views/panel/DevolucionesAdmin.vue') },
      { path: 'mensajes', name: 'panel-mensajes', component: () => import('@/views/panel/MensajesAdmin.vue') },
      { path: 'reportes', name: 'panel-reportes', component: () => import('@/views/panel/ReportesAdmin.vue') },
      {
        path: 'cupones',
        name: 'panel-cupones',
        component: () => import('@/views/panel/CuponesAdmin.vue'),
        meta: { roles: ['admin'] },
      },
      {
        path: 'usuarios',
        name: 'panel-usuarios',
        component: () => import('@/views/panel/UsuariosAdmin.vue'),
        meta: { roles: ['admin'] },
      },
    ],
  },
  { path: '/:ruta(.*)*', name: 'no-encontrado', component: () => import('@/views/NoEncontradoView.vue') },
]

const router = createRouter({
  history: createWebHistory(import.meta.env.BASE_URL),
  routes,
  scrollBehavior(to, from, posicionGuardada) {
    if (posicionGuardada) return posicionGuardada
    if (to.hash) return { el: to.hash, top: 110, behavior: 'smooth' }
    return { top: 0 }
  },
})

// Guardia global: valida la sesión y los roles antes de entrar a cada página.
router.beforeEach(async (to) => {
  const auth = useAuthStore()
  await auth.inicializar()

  if (to.matched.some((ruta) => ruta.meta.requiereSesion) && !auth.autenticado) {
    const destino = to.path.startsWith('/panel') ? 'acceso-personal' : 'login'
    return { name: destino, query: { redirect: to.fullPath } }
  }

  // Cada nivel de la ruta puede exigir roles (ej. /panel y /panel/productos/nuevo).
  const rolPermitido = to.matched.every((ruta) => !ruta.meta.roles || ruta.meta.roles.includes(auth.rol))
  if (!rolPermitido) {
    return { name: 'inicio' }
  }

  if (to.meta.soloInvitados && auth.autenticado) {
    return auth.rutaInicio
  }

  return true
})

export default router

