// Cliente de la API de Web3Forms (https://web3forms.com).
// Envía los datos del formulario de contacto directo al correo de la tienda,
// sin servidor de correo propio.
//
// La clave se lee de frontend/.env (VITE_WEB3FORMS_KEY), que no se sube al repositorio.
// Se consume desde el navegador porque así lo exige el plan gratuito de Web3Forms
// (las peticiones desde un servidor requieren plan de pago y lista blanca de IP).
// La clave de Web3Forms está pensada para usarse en el navegador: solo permite
// enviar mensajes al correo registrado, no leerlos.

const ENDPOINT = 'https://api.web3forms.com/submit'
const CLAVE = import.meta.env.VITE_WEB3FORMS_KEY?.trim() ?? ''

export default {
  /** true si hay clave configurada en el .env */
  configurado: CLAVE !== '',

  /**
   * datos: { nombre, email, telefono, motivo, mensaje, botcheck }
   * Devuelve la respuesta de Web3Forms ({ success, message }) o lanza un Error.
   */
  async enviar({ nombre, email, telefono, motivo, mensaje, botcheck = false }) {
    if (!CLAVE) throw new Error('Falta VITE_WEB3FORMS_KEY en frontend/.env')

    const respuesta = await fetch(ENDPOINT, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
      body: JSON.stringify({
        access_key: CLAVE,
        subject: `Contacto web (${motivo}) - ${nombre}`,
        from_name: 'MyA FOOTWEAR STORE',
        // Campos que llegan en el correo (Web3Forms usa "email" como dirección de respuesta)
        name: nombre,
        email,
        telefono: telefono || 'No indicado',
        motivo,
        message: mensaje,
        botcheck, // campo trampa contra bots: si viene marcado, Web3Forms lo descarta
      }),
    })

    const datos = await respuesta.json().catch(() => ({}))
    if (!respuesta.ok || !datos.success) {
      throw new Error(datos.message || datos.body?.message || `Web3Forms respondió ${respuesta.status}`)
    }
    return datos
  },
}

// Store de autenticación (Pinia): usuario actual, token JWT y rol.
import { defineStore } from 'pinia'
import { computed, ref } from 'vue'
import authService from '@/services/authService'
import { establecerToken } from '@/services/api'
import { almacenamiento } from '@/utils/formato'

const CLAVE_TOKEN = 'mya_token'

export const useAuthStore = defineStore('auth', () => {
  const token = ref(almacenamiento.leer(CLAVE_TOKEN))
  const usuario = ref(null)
  let inicializacion = null

  establecerToken(token.value)

  const autenticado = computed(() => usuario.value !== null)
  const rol = computed(() => usuario.value?.rol ?? null)
  const esAdmin = computed(() => rol.value === 'admin')
  const esPersonal = computed(() => rol.value === 'admin' || rol.value === 'vendedor')

  /** Página a la que va cada rol después de iniciar sesión. */
  const rutaInicio = computed(() => (esPersonal.value ? { name: 'panel' } : { name: 'inicio' }))

  /** Al abrir la app, si hay un token guardado se valida con la API (GET /auth/yo). */
  function inicializar() {
    inicializacion ??= (async () => {
      if (!token.value) return
      try {
        usuario.value = await authService.yo()
      } catch {
        cerrarSesion()
      }
    })()
    return inicializacion
  }

  function guardarSesion(sesion) {
    token.value = sesion.token
    usuario.value = sesion.usuario
    almacenamiento.guardar(CLAVE_TOKEN, sesion.token)
    establecerToken(sesion.token)
  }

  async function login(email, password, rolElegido = null) {
    guardarSesion(await authService.login(email, password, rolElegido))
    return usuario.value
  }

  async function registro(datos) {
    guardarSesion(await authService.registro(datos))
    return usuario.value
  }

  /** Refresca los datos del usuario después de editar su perfil. */
  function actualizarUsuario(datos) {
    usuario.value = datos
  }

  function cerrarSesion() {
    token.value = null
    usuario.value = null
    almacenamiento.borrar(CLAVE_TOKEN)
    establecerToken(null)
  }

  return { token, usuario, autenticado, rol, esAdmin, esPersonal, rutaInicio, inicializar, login, registro, actualizarUsuario, cerrarSesion }
})

// Store del carrito (Pinia). Se guarda en localStorage para no perderlo al recargar.
// Cada línea es una VARIANTE (producto + talla + color). El backend vuelve a
// validar precios y stock al crear el pedido.
import { defineStore } from 'pinia'
import { computed, ref, watch } from 'vue'
import { almacenamiento } from '@/utils/formato'

const CLAVE_CARRITO = 'mya_carrito'

/** Unidades que admite una línea: el stock, o el máximo por producto si es menor. */
export function limiteDeLinea(stock, maximoPorLinea) {
  return maximoPorLinea ? Math.min(stock, maximoPorLinea) : stock
}

// Las líneas guardadas antes de existir "limite" usan el stock.
const limiteDe = (item) => item.limite ?? item.stock

export const useCarritoStore = defineStore('carrito', () => {
  const items = ref(almacenamiento.leer(CLAVE_CARRITO, []))
  const abierto = ref(false)

  const cantidadTotal = computed(() => items.value.reduce((suma, item) => suma + item.cantidad, 0))
  const total = computed(() => items.value.reduce((suma, item) => suma + item.precio * item.cantidad, 0))

  watch(items, (valor) => almacenamiento.guardar(CLAVE_CARRITO, valor), { deep: true })

  /**
   * Agrega una variante. Nunca supera el límite de la línea: el stock disponible o el
   * máximo por producto que publica el servidor (maximo_por_linea), el que sea menor.
   * Devuelve la cantidad final.
   */
  function agregar(producto, variante, cantidad = 1) {
    const limite = limiteDeLinea(variante.stock, producto.maximo_por_linea)
    const existente = items.value.find((item) => item.varianteId === variante.id)
    if (existente) {
      existente.stock = variante.stock
      existente.limite = limite
      existente.cantidad = Math.min(limite, existente.cantidad + cantidad)
      return existente.cantidad
    }

    items.value.push({
      varianteId: variante.id,
      slug: producto.slug,
      nombre: producto.nombre,
      marca: producto.marca.nombre,
      color: variante.color.nombre,
      talla: variante.talla.valor,
      precio: producto.precio,
      imagen: producto.imagen,
      stock: variante.stock,
      limite,
      cantidad: Math.min(limite, cantidad),
    })
    return Math.min(limite, cantidad)
  }

  function cambiarCantidad(varianteId, cantidad) {
    const item = items.value.find((linea) => linea.varianteId === varianteId)
    if (item) {
      item.cantidad = Math.max(1, Math.min(limiteDe(item), cantidad))
    }
  }

  function quitar(varianteId) {
    items.value = items.value.filter((item) => item.varianteId !== varianteId)
  }

  function vaciar() {
    items.value = []
  }

  /** Actualiza los precios del carrito con los del servidor (por si una oferta empezó o terminó). */
  function actualizarPrecios(lineas) {
    for (const linea of lineas) {
      const item = items.value.find((i) => i.varianteId === linea.variante_id)
      if (item) item.precio = linea.precio
    }
  }

  return { items, abierto, cantidadTotal, total, agregar, cambiarCantidad, quitar, vaciar, actualizarPrecios, limiteDe }
})

// Store del catálogo (Pinia): marcas, tallas y colores. Se cargan una sola vez.
import { defineStore } from 'pinia'
import { ref } from 'vue'
import productoService from '@/services/productoService'

export const useCatalogoStore = defineStore('catalogo', () => {
  const marcas = ref([])
  const tallas = ref([])
  const colores = ref([])
  let carga = null

  function cargar() {
    carga ??= Promise.all([productoService.marcas(), productoService.tallas(), productoService.colores()])
      .then(([listaMarcas, listaTallas, listaColores]) => {
        marcas.value = listaMarcas
        tallas.value = listaTallas
        colores.value = listaColores
      })
      .catch((error) => {
        carga = null // Permite reintentar más tarde.
        throw error
      })
    return carga
  }

  const marcaPorSlug = (slug) => marcas.value.find((marca) => marca.slug === slug) ?? null

  return { marcas, tallas, colores, cargar, marcaPorSlug }
})

// Quita los filtros vacíos antes de enviarlos a la API (el 0 y el false sí se envían).
export const limpiarFiltros = (filtros) =>
  Object.fromEntries(Object.entries(filtros).filter(([, valor]) => valor !== '' && valor != null))

// Utilidades de formato y validación compartidas por las vistas.

const formatoPesos = new Intl.NumberFormat('es-CO', { maximumFractionDigits: 0 })

/** 399950 -> "$399.950" (mismo formato que el catálogo original). */
export function formatearPrecio(valor) {
  return `$${formatoPesos.format(Number(valor) || 0)}`
}

const formatoFecha = new Intl.DateTimeFormat('es-CO', { dateStyle: 'medium', timeStyle: 'short' })

/** "2026-11-05 14:30:00" -> "5 nov 2026, 2:30 p. m." */
export function formatearFecha(valor) {
  if (!valor) return ''
  const fecha = new Date(String(valor).replace(' ', 'T'))
  return Number.isNaN(fecha.getTime()) ? valor : formatoFecha.format(fecha)
}

